package org.sleepwell.app;
import java.util.*;import java.util.concurrent.CancellationException;import java.util.function.BooleanSupplier;
/** Explicit foreground/manual sync, with stable replay IDs and no remote calls under SQLite locks. */
final class HealthSleepSync {
 interface Local {String token();void apply(List<HealthSleep> records,List<String> deleted,String token,String ownPackage,long now);List<RecordEntry> records();HealthSleepStore.Export prepare(RecordEntry r,String ownPackage);void admit(HealthSleepStore.Export item);boolean ack(HealthSleepStore.Export item,String id);List<String> retired();void retiredDone(String id);int conflicts();void finished(long now,String summary);}
 final HealthSleepPort remote;final Local local;final String ownPackage;HealthSleepSync(HealthSleepPort remote,Local local,String ownPackage){this.remote=remote;this.local=local;this.ownPackage=ownPackage;}
 String run(boolean read,boolean write,long now,BooleanSupplier cancelled)throws Exception{
  if(!read&&!write)throw new IllegalArgumentException("Choose import or export first.");HealthSleepPort.Access access=remote.access();if(!access.available())throw new IllegalStateException(access.availability==1?"Install or update Health Connect first.":"Health Connect is unavailable on this device or profile.");if(read&&!access.granted.contains(HealthSleepPort.READ)||write&&!access.granted.contains(HealthSleepPort.WRITE))throw new SecurityException("Allow the selected sleep permissions in Health Connect first.");
  String warning="";int exported=0,removed=0,seen=0;active(cancelled);
  if(read){String token=local.token();if(!token.isEmpty()){HealthSleepPort.Changes changes=remote.changes(token);active(cancelled);if(changes.expired){warning="Change history expired; older imported copies were kept. ";token="";}else{int pages=0;Set<String> visited=new HashSet<>();while(true){if(++pages>512||!visited.add(token)||(seen+=changes.records.size()+changes.deleted.size())>10000)throw new IllegalStateException("Too many sleep changes. Retry after reducing the provider history.");local.apply(changes.records,changes.deleted,changes.next,ownPackage,now);token=changes.next;if(!changes.more)break;active(cancelled);changes=remote.changes(token);if(changes.expired)throw new IllegalStateException("Health Connect change history expired during sync. Retry.");active(cancelled);}}}
   if(token.isEmpty()){String fresh=remote.token();active(cancelled);String page=null;Set<String> pages=new HashSet<>();int count=0;do{HealthSleepPort.Page batch=remote.read(Math.max(1,now-30L*86400000),now,page);active(cancelled);if(++count>512||(seen+=batch.records.size())>10000)throw new IllegalStateException("Sleep import is too large for one manual sync.");local.apply(batch.records,List.of(),null,ownPackage,now);page=batch.next;if(page!=null&&!page.isEmpty()&&!pages.add(page))throw new IllegalStateException("Health Connect repeated a sleep page.");}while(page!=null&&!page.isEmpty());local.apply(List.of(),List.of(),fresh,ownPackage,now);
    int changePages=0;Set<String> visited=new HashSet<>();do{active(cancelled);if(++changePages>512||!visited.add(fresh))throw new IllegalStateException("Health Connect repeated a change page.");HealthSleepPort.Changes batch=remote.changes(fresh);active(cancelled);if(batch.expired)throw new IllegalStateException("Health Connect change history expired during import. Retry.");if((seen+=batch.records.size()+batch.deleted.size())>10000)throw new IllegalStateException("Too many sleep changes in one sync.");local.apply(batch.records,batch.deleted,batch.next,ownPackage,now);fresh=batch.next;if(!batch.more)break;}while(true);
   }
  }
  if(write){for(String client:local.retired()){active(cancelled);remote.delete(client);active(cancelled);local.retiredDone(client);removed++;}int count=0;for(RecordEntry r:local.records()){active(cancelled);if(++count>10000)throw new IllegalStateException("Too many local sleep records for one manual sync.");if(!r.healthConnect.isEmpty()||r.edit.end>now||r.edit.end<=r.edit.start)continue;HealthSleepStore.Export item=local.prepare(r,ownPackage);if(item==null)continue;local.admit(item);active(cancelled);String id=remote.insert(item.client,item.version,item.data,item.manual);active(cancelled);if(!local.ack(item,id))warning="Some local records changed during export; sync again. ";exported++;}}
  active(cancelled);String summary=warning+(read?"Sleep imports refreshed. ":"")+(write?exported+" exported, "+removed+" removed from your SleepWell exports. ":"")+local.conflicts()+" provider changes need review.";local.finished(now,summary);return summary;
 }
 static void active(BooleanSupplier cancelled){if(cancelled.getAsBoolean())throw new CancellationException("Sync cancelled. Completed changes were kept; retry is safe.");}
}
